import java.util.concurrent.ConcurrentHashMap
def ff = session.get()
if (ff == null) return

def hash = ff.getAttribute('image.sha256')
if (hash == null || hash.isEmpty()) {
    session.transfer(ff, REL_FAILURE)
    return
}

// In-memory LRU cache of seen hashes (thread-safe)
def cache = (ConcurrentHashMap<String, Long>) context.getExecutionNode()
if (cache == null) {
    cache = new ConcurrentHashMap<String, Long>()
}

long now = System.currentTimeMillis()
if (cache.containsKey(hash)) {
    ff = session.putAttribute(ff, 'dedup.status', 'DUPLICATE_DROPPED')
    ff = session.putAttribute(ff, 'dedup.reason', 'IMAGE_SHA256_ALREADY_EXISTS')
    log.warn("Camera pipeline detected duplicate SHA-256 hash: " + hash + " for request: " + ff.getAttribute('request_id'))
    session.transfer(ff, REL_FAILURE)
} else {
    cache.put(hash, now)
    ff = session.putAttribute(ff, 'dedup.status', 'UNIQUE_VERIFIED')
    session.transfer(ff, REL_SUCCESS)
}
